package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class SpeechStructureTest {
 static int checks;static void ok(boolean value,String label){if(!value)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 static void exact(String text,List<String> hints,int limit){SpeechLayout.Plan plan=SpeechLayout.of(text,hints);StringBuilder out=new StringBuilder();for(int at=0;at<text.length();){int end=plan.end(at,limit);if(end<=at||end-at>limit)throw new AssertionError("Invalid boundary");if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1))&&Character.isLowSurrogate(text.charAt(end)))throw new AssertionError("Split emoji");out.append(text,at,end);at=end;}if(!text.equals(out.toString()))throw new AssertionError("Dropped source text");}
 public static void main(String[] args)throws Exception{
  String value="Primeira frase completa.\n\nUm título isolado\n\nO conteúdo começa depois do título. Mais conteúdo.";SpeechLayout.Plan plan=SpeechLayout.of(value);ok(plan.titles.size()==1,"isolated heading is detected without treating prose sentences as titles");int at=value.indexOf("Um título"),end=value.indexOf("\n\nO conteúdo");ok(plan.end(0,300)==at&&plan.end(at,300)==end,"body, title and following text are separate synthesis requests");ok(plan.pauseAfter(end)==2000&&plan.pauseAfter(at)==0,"exactly two seconds are scheduled after the title only");
  String explicit="Pergunta importante?\n\nA resposta vem aqui.";SpeechLayout.Plan explicitPlan=SpeechLayout.of(explicit,Arrays.asList("Pergunta importante?"));ok(explicitPlan.titles.size()==1&&explicitPlan.pauseAfter(explicit.indexOf("\n"))==2000,"semantic heading metadata overrides terminal punctuation");
  String pdf="CAPÍTULO 2\nUma frase de conteúdo que termina aqui.";SpeechLayout.Plan pdfPlan=SpeechLayout.of(pdf);ok(pdfPlan.titles.size()==1&&pdfPlan.end(0,500)==pdf.indexOf("\n"),"uppercase PDF heading on a single line is not joined to body text");
  String windows="Introdução\r\n\r\nUm texto normal, com pontuação.";ok(SpeechLayout.of(windows).titles.size()==1,"Windows paragraph separators retain isolated heading detection");
  exact(value,Collections.emptyList(),17);exact("😀 Um título\n\nUm texto com 😀 e vírgulas, ponto e vírgula; e interrogação?",Collections.emptyList(),4);exact(explicit,Arrays.asList("Pergunta importante?"),9);ok(true,"all Unicode text reconstructs exactly across structured chunk boundaries");
  String source="";for(int i=0;i<200;i++)source+="palavra ";SpeechLayout.Plan prose=SpeechLayout.of(source);SpeechSeek.Move forward=SpeechSeek.move(source,0,10000,1,prose);ok(forward.offset>0&&source.charAt(forward.offset-1)==' ',"time skip lands on a word boundary");ok(SpeechSeek.move(source,forward.offset,-10000,1,prose).offset<=8,"opposite time skips return near the original word");ok(SpeechSeek.move(source,0,10000,2,prose).offset>forward.offset,"time skips account for selected speech speed");ok(SpeechSeek.move(source,0,-20000,1,prose).remaining==-20000,"backward overflow is retained for previous-page traversal");ok(SpeechSeek.move("Uma frase.",0,30000,1,SpeechLayout.of("Uma frase.")).remaining>0,"forward overflow is retained for next-page traversal");ok(SpeechSeek.at(value,end,1,plan)>=2000,"time model includes explicit title silence");
  Path folder=Files.createTempDirectory("seeky-title-pause-");File wave=folder.resolve("silence.wav").toFile();try{try(CheckpointWave writer=new CheckpointWave(wave,0,1,1,24000,16)){writer.silence(2000,()->false);writer.checkpoint();}WaveJoiner.Format format=WaveJoiner.inspect(wave);ok(format.length==96000&&format.rate==24000,"saved narration has precisely two seconds of 24 kHz mono PCM silence");byte[] bytes=Files.readAllBytes(wave.toPath());boolean zero=true;for(int i=44;i<bytes.length;i++)if(bytes[i]!=0)zero=false;ok(zero,"PCM pause contains only silence samples");try(CheckpointWave writer=new CheckpointWave(wave,0,1,1,8000,8)){writer.silence(2000,()->false);writer.checkpoint();}bytes=Files.readAllBytes(wave.toPath());boolean unsigned=true;for(int i=44;i<bytes.length;i++)if((bytes[i]&255)!=128)unsigned=false;ok(unsigned,"unsigned 8-bit PCM silence uses the correct midpoint");}finally{Files.deleteIfExists(wave.toPath());Files.deleteIfExists(folder);}
  System.out.println("PASS "+checks+" title pause and TTS navigation checks");
 }
}
